create type public.class_session_status as enum ('draft','scheduled','completed','cancelled');
create type public.attendance_status as enum ('pending','present','absent','late');
create table public.class_sessions (id uuid primary key default gen_random_uuid(),cohort_id uuid not null references public.cohorts(id) on delete restrict,title text not null,description text,session_date date not null,start_time time not null,end_time time not null,meeting_link text not null,status public.class_session_status not null default 'draft',created_by uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint class_sessions_title_not_blank check(length(btrim(title))>0),constraint class_sessions_title_length_check check(char_length(title)<=160),constraint class_sessions_description_length_check check(description is null or char_length(description)<=2000),constraint class_sessions_time_order_check check(end_time>start_time),constraint class_sessions_meeting_link_https_check check(meeting_link ~* '^https://[^[:space:]]+$'));
create index class_sessions_cohort_date_idx on public.class_sessions(cohort_id,session_date desc,start_time desc);create index class_sessions_status_date_idx on public.class_sessions(status,session_date,start_time);create index class_sessions_created_by_idx on public.class_sessions(created_by,session_date desc);
create table public.session_attendance(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.class_sessions(id) on delete cascade,student_id uuid not null references public.students(id) on delete restrict,status public.attendance_status not null default 'pending',marked_by uuid references public.profiles(id) on delete set null,marked_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint session_attendance_unique_student unique(session_id,student_id),constraint session_attendance_notes_length_check check(notes is null or char_length(notes)<=500));
create index session_attendance_session_status_idx on public.session_attendance(session_id,status);create index session_attendance_student_idx on public.session_attendance(student_id);
create or replace function private.populate_session_attendance() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status='scheduled'::public.class_session_status and (tg_op='INSERT' or old.status is distinct from new.status) then insert into public.session_attendance(session_id,student_id,status) select new.id,cs.student_id,'pending'::public.attendance_status from public.cohort_students cs where cs.cohort_id=new.cohort_id and cs.status='active'::public.cohort_membership_status on conflict(session_id,student_id) do nothing; end if; return new; end; $$;
create trigger class_sessions_populate_attendance after insert or update of status on public.class_sessions for each row execute function private.populate_session_attendance();
create trigger class_sessions_set_updated_at before update on public.class_sessions for each row execute function private.set_updated_at();create trigger session_attendance_set_updated_at before update on public.session_attendance for each row execute function private.set_updated_at();
alter table public.class_sessions enable row level security;alter table public.session_attendance enable row level security;revoke all on public.class_sessions,public.session_attendance from anon,authenticated;grant all on public.class_sessions,public.session_attendance to service_role;
